/* ===== src/js/00-core.js ===== */
/* ==========================================================================
   SG core
   --------------------------------------------------------------------------
   Everything in src/js is a plain script that attaches to window.SG. No
   modules, no build step for consumers, works from file://.

   CONVENTIONS for every script in this folder
   - Progressive enhancement: the HTML + CSS must already be usable. JS adds
     keyboard roving, announcements, persistence; it never creates the UI.
   - Hooks are data attributes (data-sg-*), never classes, and use event
     delegation on document, so markup added later works without re-init.
   - Wrap storage access in try/catch (private windows, blocked storage).
   - Announce state changes that have no visible focus move with SG.announce.
   - Respect SG.motion.reduced() for anything you animate from JS.
   ========================================================================== */
(function (SG) {
  'use strict';

  var root = document.documentElement;

  /** Run fn when the DOM is ready (immediately if it already is). */
  SG.ready = function (fn) {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn, { once: true });
    else fn();
  };

  SG.qs = function (sel, scope) { return (scope || document).querySelector(sel); };
  SG.qsa = function (sel, scope) { return Array.prototype.slice.call((scope || document).querySelectorAll(sel)); };

  var uidCount = 0;
  /** Unique, valid id for aria-controls / aria-labelledby wiring. */
  SG.uid = function (prefix) { return (prefix || 'sg') + '-' + ++uidCount; };

  /** localStorage that never throws. */
  SG.storage = {
    get: function (key, fallback) {
      try {
        var v = localStorage.getItem(key);
        return v == null ? fallback : JSON.parse(v);
      } catch (e) { return fallback; }
    },
    set: function (key, value) {
      try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch (e) { return false; }
    },
    remove: function (key) { try { localStorage.removeItem(key); } catch (e) { /* ignore */ } },
  };

  /* ---- Motion -----------------------------------------------------------------
     True when travel/scale/rotation should be replaced by fades. Mirrors the CSS:
     data-motion="reduced" forces it, data-motion="full" forces it off, otherwise
     follow the OS. Use it for Web Animations, View Transitions, canvas loops. */
  var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : { matches: false, addEventListener: function () {} };
  SG.motion = {
    reduced: function () {
      var m = root.getAttribute('data-motion');
      if (m === 'reduced') return true;
      if (m === 'full') return false;
      return mq.matches;
    },
  };

  /* ---- Announcements -----------------------------------------------------------
     A screen-reader-only live region. The text is cleared and set on the next
     frame so repeating the same message is announced again (WCAG 4.1.3).
       SG.announce('3 tasks left');            polite (status)
       SG.announce('Could not save', { assertive: true });   alert: use sparingly */
  var regions = {};
  function region(assertive) {
    var key = assertive ? 'alert' : 'status';
    if (regions[key]) return regions[key];
    var el = document.createElement('div');
    el.className = 'sr-only';
    el.setAttribute('role', key);
    el.setAttribute('aria-live', assertive ? 'assertive' : 'polite');
    el.setAttribute('aria-atomic', 'true');
    document.body.appendChild(el);
    regions[key] = el;
    return el;
  }
  SG.announce = function (message, opts) {
    var el = region(!!(opts && opts.assertive));
    el.textContent = '';
    window.requestAnimationFrame(function () { el.textContent = message; });
  };

  /* ---- Colour helper -------------------------------------------------------------
     Resolve any CSS colour (including var(--role) and light-dark()) to #rrggbb, e.g.
     to keep <meta name="theme-color"> in step with the canvas. */
  var cctx;
  SG.colorToHex = function (cssColor) {
    if (!cctx) { var c = document.createElement('canvas'); c.width = c.height = 1; cctx = c.getContext('2d', { willReadFrequently: true }); }
    cctx.clearRect(0, 0, 1, 1);
    cctx.fillStyle = '#000';
    cctx.fillStyle = cssColor;
    cctx.fillRect(0, 0, 1, 1);
    var d = cctx.getImageData(0, 0, 1, 1).data;
    return '#' + [d[0], d[1], d[2]].map(function (v) { return ('0' + v.toString(16)).slice(-2); }).join('');
  };
  /** Resolve a custom property (e.g. '--color-canvas') on an element to #rrggbb. */
  SG.tokenToHex = function (name, el) {
    var probe = document.createElement('i');
    probe.style.cssText = 'color:var(' + name + ');position:absolute;visibility:hidden';
    (el || root).appendChild(probe);
    var css = getComputedStyle(probe).color;
    probe.remove();
    return SG.colorToHex(css);
  };

  /* ---- Keyboard helpers shared by roving-tabindex widgets ------------------------------ */
  /** Move focus within a list of items per arrow keys. Returns the newly focused item or null. */
  SG.roving = function (items, current, key, opts) {
    var horizontal = !opts || opts.orientation !== 'vertical';
    var rtl = getComputedStyle(root).direction === 'rtl';
    var next = key === (horizontal ? (rtl ? 'ArrowLeft' : 'ArrowRight') : 'ArrowDown') ? 1
      : key === (horizontal ? (rtl ? 'ArrowRight' : 'ArrowLeft') : 'ArrowUp') ? -1 : 0;
    var i = items.indexOf(current);
    var target = null;
    if (key === 'Home') target = items[0];
    else if (key === 'End') target = items[items.length - 1];
    else if (next) {
      var n = i;
      for (var step = 0; step < items.length; step++) {
        n = (n + next + items.length) % items.length;
        if (!items[n].disabled && items[n].getAttribute('aria-disabled') !== 'true') { target = items[n]; break; }
      }
    }
    if (target) target.focus();
    return target;
  };
})((window.SG = window.SG || {}));

/* ===== src/js/05-fit.js ===== */
/* ==========================================================================
   Fit: the richest layout that fits, measured
   --------------------------------------------------------------------------
   Some rows must never wrap raggedly: a dock, a segmented control, a pager. Either the whole
   row fits on one line, or the element switches to another layout AS A WHOLE (icons only, one
   option per line, the short form). CSS cannot ask "does this fit?", so this script tries each
   layout in order, richest first, and keeps the first one in which nothing spills. It writes
   the layout to data-fit on the element; the element's CSS draws each one. For the measure to
   mean something, the CSS keeps the measured row on ONE line while data-fit is set (nowrap),
   so "does not fit" shows up as overflow instead of as a wrapped or broken word.

     SG.fit.register('.dock', {
       steps: ['labels', 'compact', 'icons'],   richest first; the last one is used when none fits
       measure: '.dock__list',                  what must not overflow (default: the element itself)
       parts: '.seg__label',                    optional: descendants that must not overflow either
       strict: true,                            optional: parts may not run into their own end padding either
       start: function (el) { return 0; },      optional: index of the first step to try
       attrs: ['aria-current']                  optional: attribute changes inside that re-check
     })
     SG.fit.update()                            re-check everything now

   It re-checks when an element's size changes (a rotation, the reader's text size), when fonts
   load, when a matching element is added, and when one of attrs changes inside one. Without JS
   there is no data-fit, and each element's CSS has its own fallback (it wraps, or it scrolls).
   ========================================================================== */
(function (SG) {
  'use strict';

  var kinds = [];
  var watched = [];
  var frame = 0;
  var ro = 'ResizeObserver' in window ? new ResizeObserver(schedule) : null;
  var mo = null;
  var attrNames = ['hidden'];

  function overflows(node) {
    return node.scrollWidth > node.clientWidth + 1;
  }

  /* Content that runs into an element's end padding without passing its padding box does not change scrollWidth
     (and scrollWidth is rounded), so a word 0.9px into a row's padding read as "fits". With strict: true the parts
     are also measured against their content box, to half a pixel. */
  function runsIntoPadding(node) {
    var cs = getComputedStyle(node);
    var box = node.getBoundingClientRect();
    var rtl = cs.direction === 'rtl';
    var edge = rtl ? box.left + parseFloat(cs.borderLeftWidth) + parseFloat(cs.paddingLeft)
      : box.right - parseFloat(cs.borderRightWidth) - parseFloat(cs.paddingRight);
    var range = document.createRange();
    range.selectNodeContents(node);
    var rects = range.getClientRects();
    for (var i = 0; i < rects.length; i++) {
      var q = rects[i];
      if (q.width < 1) continue;
      if (rtl ? q.left < edge - 0.5 : q.right > edge + 0.5) return true;
    }
    return false;
  }

  function fits(el, kind) {
    var box = kind.measure ? el.querySelector(kind.measure) : el;
    if (!box || overflows(box)) return !box;
    if (!kind.parts) return true;
    var parts = el.querySelectorAll(kind.parts);
    for (var i = 0; i < parts.length; i++) if (overflows(parts[i]) || (kind.strict && runsIntoPadding(parts[i]))) return false;
    return true;
  }

  function fitOne(el, kind) {
    var steps = kind.steps;
    var from = kind.start ? Math.max(0, Math.min(steps.length - 1, kind.start(el) || 0)) : 0;
    for (var i = from; i < steps.length; i++) {
      if (el.getAttribute('data-fit') !== steps[i]) el.setAttribute('data-fit', steps[i]);
      if (i === steps.length - 1 || fits(el, kind)) return;
    }
  }

  function update() {
    frame = 0;
    kinds.forEach(function (kind) {
      SG.qsa(kind.selector).forEach(function (el) {
        if (ro && watched.indexOf(el) < 0) { watched.push(el); ro.observe(el); }
        fitOne(el, kind);
      });
    });
    watched = watched.filter(function (el) {
      if (el.isConnected) return true;
      if (ro) ro.unobserve(el);
      return false;
    });
  }

  function schedule() {
    if (!frame) frame = window.requestAnimationFrame(update);
  }

  function matchesAny(node) {
    if (!node || node.nodeType !== 1) return false;
    for (var i = 0; i < kinds.length; i++) {
      var sel = kinds[i].selector;
      if (node.closest(sel) || node.querySelector(sel)) return true;
    }
    return false;
  }

  function observe() {
    if (!('MutationObserver' in window)) return;
    if (mo) mo.disconnect();
    mo = new MutationObserver(function (records) {
      for (var i = 0; i < records.length; i++) {
        var r = records[i];
        if (r.type === 'attributes' ? matchesAny(r.target) : r.addedNodes.length && matchesAny(r.target)) {
          schedule();
          return;
        }
      }
    });
    mo.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: attrNames });
  }

  var started = false;

  SG.fit = {
    register: function (selector, opts) {
      var kind = { selector: selector, steps: opts.steps, measure: opts.measure, parts: opts.parts, start: opts.start, strict: opts.strict };
      kinds.push(kind);
      (opts.attrs || []).forEach(function (a) { if (attrNames.indexOf(a) < 0) attrNames.push(a); });
      if (started) { observe(); schedule(); }
    },
    update: update
  };

  SG.ready(function () {
    started = true;
    update();
    observe();
    window.addEventListener('resize', schedule);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(schedule);
  });
})((window.SG = window.SG || {}));

/* ===== src/js/10-prefs.js ===== */
/* ==========================================================================
   SG.prefs: user-chosen appearance, persisted, applied as data-* on <html>
   --------------------------------------------------------------------------
     SG.prefs.set('theme', 'dark')      light | dark | system
     SG.prefs.set('contrast', 'more')   more | system
     SG.prefs.set('palette', 'mint')    default | mint | periwinkle | sand | cream | wire | ...
     SG.prefs.set('corners', 'soft')    square (default) | soft
     SG.prefs.set('motion', 'reduced')  reduced | full | system
     SG.prefs.get('theme')              -> 'system' when unset
     SG.prefs.onChange(fn)              fn(name, value)
     SG.prefs.reset()

   "system" means: remove the attribute and follow the OS (prefers-color-scheme,
   prefers-contrast, prefers-reduced-motion). Give users a settings screen with
   these five controls in every app; some people cannot change OS settings.

   YOUR APP'S OWN LOOK. Author it as attributes on <html> (<html data-palette="mint" data-corners="soft">).
   Choosing the guide's own default ("default", "square") then writes that value explicitly, so it wins over
   what you authored; and reset() puts your authored attributes back instead of stripping them.

   TWO APPS ON ONE ORIGIN share localStorage. Give each its own key on <html>:
     <html data-sg-prefs-key="flashcards:prefs">
   (read once, when the script loads; use the same key in the head snippet below).

   AVOID A FLASH OF THE WRONG THEME: apply the saved values before first paint
   with this inline snippet in <head> (before the stylesheet):
     <script>try{var p=JSON.parse(localStorage.getItem('sg:prefs')||'{}');for(var k in p)document.documentElement.setAttribute('data-'+k,p[k])}catch(e){}</script>
   With your own key, replace 'sg:prefs' there with the same string.
   ========================================================================== */
(function (SG) {
  'use strict';

  var root = document.documentElement;
  var STORE = root.getAttribute('data-sg-prefs-key') || 'sg:prefs';
  var NAMES = ['theme', 'contrast', 'palette', 'corners', 'motion'];
  var DEFAULT_VALUE = { palette: 'default', corners: 'square' }; // the guide's own values; they mean "no attribute" unless the app authored another
  var listeners = [];

  function saved() { return SG.storage.get(STORE, {}) || {}; }

  // What the app wrote on <html> itself. When a choice is saved over it, the original is kept under "was-<name>"
  // (the head snippet copies it to a harmless data-was-* attribute); otherwise a value that differs from the
  // saved one, or any value when nothing is saved, is the app's own.
  var authored = {};
  (function () {
    var s = saved();
    NAMES.forEach(function (n) {
      var cur = root.getAttribute('data-' + n);
      authored[n] = s['was-' + n] != null ? s['was-' + n] : (cur != null && s[n] !== cur ? cur : null);
    });
  })();

  /** Must this choice be stored? Not if it just means "what the app wrote" or "nothing at all". */
  function explicit(name, value) {
    if (value == null || value === '') return false;
    if (value === authored[name]) return false;
    if (value === 'system' || value === DEFAULT_VALUE[name]) return authored[name] != null; // these need writing down only to override the app's own
    return true;
  }

  function apply(name, value) {
    var plain = value == null || value === '' || value === 'system' || (value === DEFAULT_VALUE[name] && authored[name] == null);
    if (plain) root.removeAttribute('data-' + name);
    else root.setAttribute('data-' + name, value);
  }

  /** Keep the browser UI colour in step when the user overrides the OS theme. */
  function syncThemeColor() {
    var metas = SG.qsa('meta[name="theme-color"]');
    if (!metas.length) return;
    var overridden = root.hasAttribute('data-theme') || root.hasAttribute('data-palette');
    if (!overridden) {
      // restore the media-query originals
      metas.forEach(function (m) { if (m.dataset.sgOriginal) { m.content = m.dataset.sgOriginal; } });
      return;
    }
    var hex = SG.tokenToHex('--canvas');
    metas.forEach(function (m) {
      if (!m.dataset.sgOriginal) m.dataset.sgOriginal = m.content;
      m.content = hex;
    });
  }

  SG.prefs = {
    names: NAMES,
    get: function (name) {
      var v = root.getAttribute('data-' + name);
      return v == null ? (DEFAULT_VALUE[name] && !root.hasAttribute('data-' + name) ? DEFAULT_VALUE[name] : 'system') : v;
    },
    set: function (name, value) {
      if (NAMES.indexOf(name) < 0) throw new Error('SG.prefs: unknown preference "' + name + '"');
      apply(name, value);
      var s = saved();
      if (explicit(name, value)) {
        s[name] = value;
        if (authored[name] != null) s['was-' + name] = authored[name];
      } else {
        delete s[name];
        delete s['was-' + name];
      }
      if (Object.keys(s).length) SG.storage.set(STORE, s); else SG.storage.remove(STORE);
      syncThemeColor();
      listeners.forEach(function (fn) { fn(name, SG.prefs.get(name)); });
    },
    reset: function () {
      NAMES.forEach(function (n) {
        if (authored[n] != null) root.setAttribute('data-' + n, authored[n]); else root.removeAttribute('data-' + n);
      });
      SG.storage.remove(STORE);
      syncThemeColor();
      listeners.forEach(function (fn) { fn('*', null); });
    },
    onChange: function (fn) { listeners.push(fn); },
    all: function () {
      var o = {};
      NAMES.forEach(function (n) { o[n] = SG.prefs.get(n); });
      return o;
    },
  };

  // Apply saved values (idempotent if the inline snippet already did).
  var s = saved();
  NAMES.forEach(function (n) { if (s[n] != null) apply(n, s[n]); });
  SG.ready(syncThemeColor);
})((window.SG = window.SG || {}));

/* ===== src/js/20-guard.js ===== */
/* ==========================================================================
   Disabled-but-focusable guard
   --------------------------------------------------------------------------
   Prefer aria-disabled="true" over the disabled attribute for controls a user
   may need to understand ("Why can't I press Save?"): it stays focusable and
   can be described with aria-describedby. But aria-disabled does nothing on its
   own: a keyboard user can still press Enter or Space. This guard makes it
   inert for clicks and keys, for every button, link and role=button, now and
   later. It is capture-phase so app handlers never see the event.
   ========================================================================== */
(function (SG) {
  'use strict';

  function disabledTarget(e) {
    var t = e.target;
    return t && t.closest ? t.closest('[aria-disabled="true"]') : null;
  }

  document.addEventListener('click', function (e) {
    if (disabledTarget(e)) { e.preventDefault(); e.stopImmediatePropagation(); }
  }, true);

  document.addEventListener('keydown', function (e) {
    if ((e.key === 'Enter' || e.key === ' ') && disabledTarget(e)) { e.preventDefault(); e.stopImmediatePropagation(); }
  }, true);

  SG.guard = true;
})((window.SG = window.SG || {}));

/* ===== src/js/25-disclosure.js ===== */
/* ==========================================================================
   Disclosure: a button that shows and hides what it controls
   --------------------------------------------------------------------------
   The WAI-ARIA Authoring Practices "disclosure" pattern. Use it for a card panel
   that folds away, a "Show answer" button, an FAQ row: anything where one button
   opens one region and the region does not need its own focus management.

     <button class="card__ctl" type="button" aria-label="Decks"
             aria-expanded="true" aria-controls="decks-body" data-sg-toggle>
     <div id="decks-body">…</div>

   · The button keeps ONE name; aria-expanded tells a screen reader the state.
     Do not swap the label AND set aria-expanded: that announces the state twice.
   · The region is shown/hidden with the `hidden` attribute, so there is no
     animation to reduce and nothing to get out of step with the state.
   · data-sg-announce on the button reads the revealed text aloud politely (for
     an answer that appears somewhere the user is not looking). SG.announce is a
     live region, so nothing moves focus.
   · Start state comes from aria-expanded in the HTML; this script makes `hidden`
     agree with it on load, so the two can never disagree.
   Native <details>/<summary> does the same with no JS when the control can be
   the whole summary; prefer it when it fits.
   ========================================================================== */
(function (SG) {
  'use strict';

  function region(btn) {
    var id = btn.getAttribute('aria-controls');
    return id ? document.getElementById(id) : null;
  }

  /** Open or close the region a toggle controls. Returns the new state. */
  SG.toggle = function (btn, open) {
    var target = region(btn);
    if (!target) return null;
    if (open === undefined) open = btn.getAttribute('aria-expanded') !== 'true';
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    target.hidden = !open;
    if (open && btn.hasAttribute('data-sg-announce') && SG.announce) SG.announce(target.textContent.replace(/\s+/g, ' ').trim());
    return open;
  };

  document.addEventListener('click', function (e) {
    var btn = e.target && e.target.closest ? e.target.closest('[data-sg-toggle]') : null;
    if (btn) SG.toggle(btn);
  });

  function sync() {
    var all = document.querySelectorAll('[data-sg-toggle][aria-controls]');
    for (var i = 0; i < all.length; i++) {
      var target = region(all[i]);
      if (target) target.hidden = all[i].getAttribute('aria-expanded') !== 'true';
    }
  }
  if (SG.ready) SG.ready(sync);
  else if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', sync);
  else sync();
})((window.SG = window.SG || {}));
